{"items":[
    {"kind":"stakeholder","quote":"Nurses on the oncology ward"},
    {"kind":"requirement","quote":"that they can program quickly at the bedside"},
    {"kind":"requirement","quote":"The pump shall deliver a programmed rate between 0.1 and 999 ml/h"},
    {"kind":"requirement","quote":"with an accuracy of plus or minus 5 percent"},
    {"kind":"requirement","quote":"It must raise an audible alarm when an occlusion is detected"},
    {"kind":"requirement","quote":"The pump must comply with IEC 60601-2-24"},
