{"items":[
    {"kind":"stakeholder","quote":"Regional railway operators"},
    {"kind":"objective","quote":"increase line capacity without building new track"},
    {"kind":"requirement","quote":"The on-board unit reports its position to the trackside controller every second"},
    {"kind":"requirement","quote":"The trackside controller shall grant movement authority only if the block ahead is confirmed clear"},
    {"kind":"requirement","quote":"The system shall not rely on GPS alone for positioning"},
    {"kind":"constraint","quote":"Safety assessors will require evidence at safety integrity level 4"}
    ],
"ambiguities":[]}

{"items":[
    {"kind":"stakeholder","quote":"The facilities manager"},
    {"kind":"objective","quote":"cut cooling energy"},
    {"kind":"requirement","quote":"Rack inlet temperature must stay below 27 degrees Celsius"},
    {"kind":"assumption","quote":"server load will remain roughly constant over the next two years"}
    ],
"ambiguities":[]}

{"items":[
    {"kind":"stakeholder","quote":"The depot manager"},
    {"kind":"objective","quote":"which buses are late to charge"},
    {"kind":"requirement","quote":"Buses must be fully charged by 05:00 every morning"},
    {"kind":"constraint","quote":"total draw to the grid connection limit of 2 MW"},
    {"kind":"system_element","quote":"the energy management system"},
    {"kind":"function","quote":"sends a charging schedule to each charger"},
    {"kind":"system_element","quote":"Charger vendors"}
    ],
"ambiguities":[]}

{"items":[
